const ceny = new Map([["chleb", 5], ["mleko", 4], ["maslo", 9]]);

for (const [nazwa, cena] of ceny) {
  console.log(`${nazwa}: ${cena}`);
}
// "chleb: 5"
// "mleko: 4"
// "maslo: 9"

const ceny = new Map([["chleb", 5], ["mleko", 4], ["maslo", 9]]);

ceny.forEach((cena, nazwa) => {
  console.log(`${nazwa}: ${cena}`);
});
// "chleb: 5"
// "mleko: 4"
// "maslo: 9"

const mecze = new Map([["Polska", 2], ["Niemcy", 1], ["Francja", 3]]);

let suma = 0;
for (const [, wynik] of mecze) {
  suma += wynik;
}
console.log(suma); // 6

const mapa = new Map([["a", 1], ["b", 2], ["c", 3]]);

const pary = [...mapa.entries()].map(([klucz, wartosc]) => `${klucz}=${wartosc}`);
console.log(pary); // ["a=1", "b=2", "c=3"]

// Kolejnosc (wartosc, klucz) w forEach dla Map czesto zaskakuje, poniewaz
// wieksza intuicja podpowiada "klucz najpierw" (tak jak w destrukturyzacji
// [klucz, wartosc] w for...of). Kolejnosc ta wynika jednak z HISTORYCZNEJ
// spojnosci z .forEach() na tablicach, gdzie sygnatura to
// (element, indeks, tablica) - "glowna wartosc" (element/wartosc) jest
// zawsze PIERWSZYM argumentem, a "identyfikator" (indeks/klucz) DRUGIM.
//
// Sposob na zapamietanie: w forEach ZAWSZE 'to, co przechowujesz' (wartosc/
// element) jest pierwsze, a 'to, czym to jest zaindeksowane' (klucz/
// indeks) jest drugie - zarowno dla tablic, jak i dla Map.

const ceny = new Map([["chleb", 5], ["mleko", 4], ["maslo", 9]]);

[...ceny].forEach(([klucz, wartosc], i) => {
  console.log(i + 1 + ". " + klucz + ": " + wartosc);
});
// -> "1. chleb: 5"
// -> "2. mleko: 4"
// -> "3. maslo: 9"

const ceny = new Map([["chleb", 5], ["mleko", 4], ["maslo", 9]]);
const drozsza = new Map([...ceny].map(([k, v]) => [k, v * 1.1]));

console.log(drozsza.get("maslo").toFixed(2)); // -> "9.90"
console.log(ceny.get("maslo"));               // -> 9 (oryginal bez zmian)

const ceny = new Map([["chleb", 5], ["mleko", 4], ["maslo", 9]]);
const drogie = new Map([...ceny].filter(([k, v]) => v > 4));

console.log([...drogie.keys()]); // -> ["chleb", "maslo"]

const ceny = new Map([["chleb", 5], ["mleko", 4], ["maslo", 9]]);
const posortowana = new Map([...ceny].sort((a, b) => b[1] - a[1]));

console.log([...posortowana.keys()]); // -> ["maslo", "chleb", "mleko"]

const m = new Map([["b", 1], ["c", 2], ["a", 3]]);
const posortowana = new Map([...m].sort((x, y) => x[0].localeCompare(y[0])));

console.log([...posortowana.keys()]); // -> ["a", "b", "c"]

function kluczZNajwiekszaWartoscia(mapa) {
  let najlepszyKlucz;
  let najlepszaWartosc = -Infinity;

  for (const [klucz, wartosc] of mapa) {
    if (wartosc > najlepszaWartosc) {
      najlepszaWartosc = wartosc;
      najlepszyKlucz = klucz;
    }
  }
  return najlepszyKlucz;
}

console.log(kluczZNajwiekszaWartoscia(new Map([["a", 3], ["b", 9], ["c", 5]]))); // -> "b"

const ceny = new Map([["chleb", 5], ["mleko", 4]]);
const lista = [...ceny].map(([nazwa, cena]) => ({ nazwa, cena }));

console.log(lista); // -> [{ nazwa: "chleb", cena: 5 }, { nazwa: "mleko", cena: 4 }]

const uzytkownicy = [{ id: 1, imie: "Ala" }, { id: 2, imie: "Jan" }];
const poId = new Map(uzytkownicy.map(o => [o.id, o]));

console.log(poId.get(2).imie); // -> "Jan"
console.log(poId.has(3));      // -> false

const mapa = new Map([["a", 1], ["b", 2]]);
const it = mapa.keys();

console.log([...it]); // -> ["a", "b"]
console.log([...it]); // -> [] (iterator zostal wyczerpany)
console.log([...mapa.keys()]); // -> ["a", "b"] (nowe wywolanie keys() daje swiezy iterator)

const mapa = new Map([["a", 1], ["b", 2]]);
const it = mapa.entries();

let wynik = it.next();
while (!wynik.done) {
  console.log(wynik.value); // -> ["a", 1], potem ["b", 2]
  wynik = it.next();
}
console.log(wynik);         // -> { value: undefined, done: true }

const m = new Map([["a", 1], ["b", 5], ["c", 7]]);
let znaleziony;

for (const [klucz, wartosc] of m) {
  if (wartosc > 4) {
    znaleziony = klucz;
    break;
  }
}

console.log(znaleziony); // -> "b"
// forEach nie pozwala przerwac iteracji (break nie dziala w callbacku).

const dzialy = new Map([
  ["IT", new Map([["Ala", 100], ["Jan", 120]])],
  ["HR", new Map([["Ola", 80]])]
]);

for (const [dzial, pracownicy] of dzialy) {
  let suma = 0;
  for (const [, pensja] of pracownicy) suma += pensja;
  console.log(dzial + ": " + suma);
}
// -> "IT: 220"
// -> "HR: 80"

const transakcje = [
  { kat: "jedzenie", kwota: 10 },
  { kat: "dom", kwota: 50 },
  { kat: "jedzenie", kwota: 5 }
];

const sumy = new Map();
for (const { kat, kwota } of transakcje) {
  sumy.set(kat, (sumy.get(kat) || 0) + kwota);
}

console.log([...sumy]); // -> [["jedzenie", 15], ["dom", 50]]

const m = new Map([["a", 1], ["b", 2], ["c", 3]]);
const odwiedzone = [];

for (const [k, v] of m) {
  odwiedzone.push(k);
  m.set(k, v * 2);
}

console.log(odwiedzone); // -> ["a", "b", "c"]
console.log([...m]);     // -> [["a", 2], ["b", 4], ["c", 6]]

const m = new Map([["tmp_1", 1], ["a", 2], ["tmp_2", 3], ["b", 4]]);

for (const [k] of m) {
  if (k.startsWith("tmp_")) m.delete(k);
}

console.log([...m.keys()]); // -> ["a", "b"]

const m = new Map([["a", 1]]);

for (const k in m) console.log("in:", k);        // nic nie wypisuje
for (const [k, v] of m) console.log("of:", k, v); // -> "of:" "a" 1
// for...in wylicza wlasciwosci obiektu, a wpisy Map sa dostepne tylko przez iterator (for...of).

const m = new Map([["a", 1], ["b", 2], ["c", 3]]);
const odwrocona = new Map([...m].reverse());

console.log([...m.keys()]);         // -> ["a", "b", "c"]
console.log([...odwrocona.keys()]); // -> ["c", "b", "a"]

const kot = { nazwa: "kot" };
const pies = { nazwa: "pies" };
const m = new Map([[kot, 3], [pies, 5]]);

for (const [zwierze, ile] of m) {
  console.log(zwierze.nazwa + ": " + ile);
}
// -> "kot: 3"
// -> "pies: 5"

const m = new Map([["x", 1], ["y", 2]]);

console.log([...m.keys()].join(", "));                               // -> "x, y"
console.log([...m].map(([k, v]) => k + "=" + v).join("&"));          // -> "x=1&y=2"

const m = new Map([["a", 1], ["b", 2]]);

for (const [k, v] of m) {}                       // for...of: break, continue, destrukturyzacja
m.forEach((v, k) => {});                         // forEach: zwiezle, ale bez break (uwaga na kolejnosc: wartosc, klucz)
const klucze = [...m.keys()];                    // spread: mozna uzyc map, filter, sort itd.
const wartosci = [...m.values()];
const pary = [...m.entries()];

console.log(klucze, wartosci, pary); // -> ["a", "b"] [1, 2] [["a", 1], ["b", 2]]

